create table xxventuri.eba_sales_deals (
    id                      number,
    row_version_number      number(*, 0),
    row_key                 varchar2(255 byte),
    tags                    varchar2(4000 byte),
    deal_currency           varchar2(8 byte),
    customer_id             number not null enable,
    salesrep_id_01          number,
    salesrep_id_02          number,
    salesrep_id_03          number,
    salesrep_id_04          number,
    team_members            varchar2(4000 byte),
    vp_id                   number,
    svp_id                  number,
    deal_name               varchar2(255 byte),
    territory_id_old        number,
    deal_close_date         timestamp(6) with local time zone not null enable,
    deal_close_date_alt     timestamp(6) with local time zone,
    deal_probability        number(*, 0),
    deal_stage              number,
    deal_amount             number,
    deal_license            number,
    deal_support            number,
    deal_education          number,
    deal_consulting         number,
    deal_status_code_id     number,
    deal_customer_location  varchar2(4000 byte),
    deal_contacts           varchar2(4000 byte),
    deal_summary            varchar2(4000 byte),
    deal_system_id          varchar2(30 byte),
    deal_products           varchar2(4000 byte),
    deal_competitors        varchar2(4000 byte),
    strategy                varchar2(4000 byte),
    financial_assessment_id number,
    status_assessment_id    number,
    risk_assessment_id      number,
    account_standing_id     number,
    pro_re_active           varchar2(30 byte),
    national_top_25_yn      varchar2(1 byte),
    partner                 varchar2(1 byte),
    created_by              varchar2(255 byte),
    created                 timestamp(6) with local time zone,
    updated_by              varchar2(255 byte),
    updated                 timestamp(6) with local time zone,
    qtr                     varchar2(8 byte),
    external_opportunity_id varchar2(512 byte),
    internal_flex_flag_01   varchar2(30 byte),
    internal_flex_flag_02   varchar2(30 byte),
    internal_flex_flag_03   varchar2(30 byte),
    internal_flex_flag_04   varchar2(30 byte),
    internal_flex_01        varchar2(4000 byte),
    internal_flex_02        varchar2(4000 byte),
    internal_flex_03        varchar2(4000 byte),
    internal_flex_04        varchar2(4000 byte),
    flex_flag_01            varchar2(30 byte),
    flex_flag_02            varchar2(30 byte),
    flex_flag_03            varchar2(30 byte),
    flex_flag_04            varchar2(30 byte),
    flex_flag_05            varchar2(30 byte),
    flex_flag_06            varchar2(30 byte),
    flex_flag_07            varchar2(30 byte),
    flex_flag_08            varchar2(30 byte),
    flex_01                 varchar2(4000 byte),
    flex_02                 varchar2(4000 byte),
    flex_03                 varchar2(4000 byte),
    flex_04                 varchar2(4000 byte),
    flex_05                 varchar2(4000 byte),
    flex_06                 varchar2(4000 byte),
    flex_07                 varchar2(4000 byte),
    flex_08                 varchar2(4000 byte),
    flex_d01                timestamp(6) with local time zone,
    flex_d02                timestamp(6) with local time zone,
    flex_d03                timestamp(6) with local time zone,
    flex_d04                timestamp(6) with local time zone,
    flex_n01                number,
    flex_n02                number,
    flex_n03                number,
    flex_n04                number,
    flex_n05                number,
    flex_n06                number,
    flex_n07                number,
    flex_n08                number,
    location_id             number,
    source_type             char(1 byte),
    quote_type_id           number
);

alter table xxventuri.eba_sales_deals
    add constraint eba_sales_deals_prob_cc check ( deal_probability between 0 and 100 ) enable;

alter table xxventuri.eba_sales_deals add primary key ( id )
    using index enable;


